param(
    [string]$Path,
    [string]$Destination
)

$original = [System.IO.File]::ReadAllText($Path)
$sb = [System.Text.StringBuilder]::new($original.Length * 3)
$pos = $original.IndexOf("`npublic") + 1
$original = $original.Substring($pos)
$null = $sb.AppendLine(@'
// Copyright (c) Matthias Wolf, Mawosoft.

// <auto-generated />

#nullable enable

using System.Management.Automation;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using InvocationTestFixture.Arguments;

namespace InvocationTestFixture;

'@)

$content = $original
$content = [regex]::Replace($content, '\bDefaultMethodProvider\b', 'NonPublicMethodProvider')
$content = [regex]::Replace($content, '\bpublic void\b', 'internal void')
$null = $sb.Append($content)
$null = $sb.AppendLine()

$content = $original
$content = [regex]::Replace($content, '\bDefaultMethodProvider\b', 'StaticMethodProvider')
$content = [regex]::Replace($content, '\bpublic void.*?\(', '$0PSObject pso, ')
$content = [regex]::Replace($content, '\bpublic void\b', 'public static void')
$content = [regex]::Replace($content, '(\bLog(?:Enter|Exit)\s*\(\s*)this\b', '$1pso')
$null = $sb.Append($content)

[System.IO.File]::WriteAllText($Destination, $sb.ToString())
